import modelsList from './models.json'
import { createAnthropic } from '@ai-sdk/anthropic'
import { createFireworks } from '@ai-sdk/fireworks'
import { createGoogleGenerativeAI } from '@ai-sdk/google'
import { createVertex } from '@ai-sdk/google-vertex'
import { createMistral } from '@ai-sdk/mistral'
import { createOpenAI } from '@ai-sdk/openai'
import { createOllama } from 'ollama-ai-provider'

export type LLMModel = {
  id: string
  name: string
  provider: string
  providerId: string
}

export type LLMModelConfig = {
  model?: string
  apiKey?: string
  temperature?: number
  topP?: number
  topK?: number
  frequencyPenalty?: number
  presencePenalty?: number
  maxTokens?: number
}

// Finds the model in models.json. Ollama models are only available when
// OLLAMA_BASE_URL is set.
export function resolveModel(id: unknown): LLMModel | undefined {
  const model = modelsList.models.find((model) => model.id === id)
  if (model?.providerId === 'ollama' && !process.env.OLLAMA_BASE_URL) {
    return undefined
  }
  return model
}

// Providers that call the API with the caller's key when one is provided.
// Vertex and Ollama always use the server's configuration.
const clientKeyProviders = new Set([
  'anthropic',
  'openai',
  'google',
  'mistral',
  'groq',
  'togetherai',
  'fireworks',
  'xai',
  'deepseek',
])

// Returns the caller's API key when the request will be sent with it.
// Without one, the request uses the server's keys.
export function getClientApiKey(
  model: LLMModel,
  config: LLMModelConfig,
): string | undefined {
  const { apiKey } = config
  if (typeof apiKey !== 'string' || apiKey.length === 0) {
    return undefined
  }
  return clientKeyProviders.has(model.providerId) ? apiKey : undefined
}

export function getModelParams(config: LLMModelConfig) {
  const {
    temperature,
    topP,
    topK,
    frequencyPenalty,
    presencePenalty,
    maxTokens,
  } = config
  return {
    temperature,
    topP,
    topK,
    frequencyPenalty,
    presencePenalty,
    maxTokens,
  }
}

export function getModelClient(model: LLMModel, config: LLMModelConfig) {
  const { id: modelNameString, providerId } = model
  const apiKey = getClientApiKey(model, config)

  const providerConfigs = {
    anthropic: () => createAnthropic({ apiKey })(modelNameString),
    openai: () => createOpenAI({ apiKey })(modelNameString),
    google: () => createGoogleGenerativeAI({ apiKey })(modelNameString),
    mistral: () => createMistral({ apiKey })(modelNameString),
    groq: () =>
      createOpenAI({
        apiKey: apiKey || process.env.GROQ_API_KEY,
        baseURL: 'https://api.groq.com/openai/v1',
      })(modelNameString),
    togetherai: () =>
      createOpenAI({
        apiKey: apiKey || process.env.TOGETHER_API_KEY,
        baseURL: 'https://api.together.xyz/v1',
      })(modelNameString),
    ollama: () =>
      createOllama({ baseURL: process.env.OLLAMA_BASE_URL })(modelNameString),
    fireworks: () =>
      createFireworks({
        apiKey: apiKey || process.env.FIREWORKS_API_KEY,
        baseURL: 'https://api.fireworks.ai/inference/v1',
      })(modelNameString),
    vertex: () =>
      createVertex({
        googleAuthOptions: {
          credentials: JSON.parse(
            process.env.GOOGLE_VERTEX_CREDENTIALS || '{}',
          ),
        },
      })(modelNameString),
    xai: () =>
      createOpenAI({
        apiKey: apiKey || process.env.XAI_API_KEY,
        baseURL: 'https://api.x.ai/v1',
      })(modelNameString),
    deepseek: () =>
      createOpenAI({
        apiKey: apiKey || process.env.DEEPSEEK_API_KEY,
        baseURL: 'https://api.deepseek.com/v1',
      })(modelNameString),
  }

  const createClient =
    providerConfigs[providerId as keyof typeof providerConfigs]

  if (!createClient) {
    throw new Error(`Unsupported provider: ${providerId}`)
  }

  return createClient()
}

/**
 * Shared error handling utilities for API routes
 */

export interface APIError {
  statusCode?: number
  message: string
}

/**
 * Checks if an error is a rate limit error
 */
export function isRateLimitError(error: any): boolean {
  return (
    error &&
    (error.statusCode === 429 ||
      error.message.toLowerCase().includes('limit') ||
      error.message.toLowerCase().includes('billing'))
  )
}

/**
 * Checks if an error is an overloaded/unavailable error
 */
export function isOverloadedError(error: any): boolean {
  return error && (error.statusCode === 529 || error.statusCode === 503)
}

/**
 * Checks if an error is an access denied/unauthorized error
 */
export function isAccessDeniedError(error: any): boolean {
  return error && (error.statusCode === 403 || error.statusCode === 401)
}

/**
 * Handles API errors and returns appropriate Response objects
 */
export function handleAPIError(
  error: any,
  context?: { hasOwnApiKey?: boolean },
): Response {
  // Log the error for debugging
  console.error('API Error:', error)

  if (isRateLimitError(error)) {
    const message = context?.hasOwnApiKey
      ? 'The provider is currently unavailable due to request limit.'
      : 'The provider is currently unavailable due to request limit. Try using your own API key.'

    return new Response(message, { status: 429 })
  }

  if (isOverloadedError(error)) {
    return new Response(
      'The provider is currently unavailable. Please try again later.',
      { status: 529 },
    )
  }

  if (isAccessDeniedError(error)) {
    return new Response(
      'Access denied. Please make sure your API key is valid.',
      { status: 403 },
    )
  }

  // Generic error handling
  return new Response(
    'An unexpected error has occurred. Please try again later.',
    { status: 500 },
  )
}

/**
 * Creates rate limit response with headers
 */
export function createRateLimitResponse(limit: {
  amount: number
  remaining: number
  reset: number
}): Response {
  return new Response('You have reached your request limit for the day.', {
    status: 429,
    headers: {
      'X-RateLimit-Limit': limit.amount.toString(),
      'X-RateLimit-Remaining': limit.remaining.toString(),
      'X-RateLimit-Reset': limit.reset.toString(),
    },
  })
}

